CREATE   PROCEDURE [synapse_ce].[usp_Insert_apuk_availability]
AS
BEGIN
	INSERT INTO [synapse_ce].[apuk_availability]
	(
		[apuk_assessmentevent],
		[apuk_assessmentevent_entitytype],
		[apuk_assessmenteventname],
		[apuk_assessor],
		[apuk_assessor_entitytype],
		[apuk_assessorname],
		[apuk_availabilityhours],
		[apuk_availabilityid],
		[apuk_availabilitytype],
		[apuk_availabiltyhours],
		[apuk_contactid],
		[apuk_contactid_entitytype],
		[apuk_contactidname],
		[apuk_contactidyominame],
		[apuk_enddate],
		[apuk_errormessage],
		[apuk_maximumnumberofdays],
		[apuk_name],
		[apuk_startdate],
		[createdby],
		[createdby_entitytype],
		[createdbyname],
		[createdbyyominame],
		[createdon],
		[createdonbehalfby],
		[createdonbehalfby_entitytype],
		[createdonbehalfbyname],
		[createdonbehalfbyyominame],
		[Id],
		[importsequencenumber],
		[modifiedby],
		[modifiedby_entitytype],
		[modifiedbyname],
		[modifiedbyyominame],
		[modifiedon],
		[modifiedonbehalfby],
		[modifiedonbehalfby_entitytype],
		[modifiedonbehalfbyname],
		[modifiedonbehalfbyyominame],
		[organizationid],
		[organizationid_entitytype],
		[organizationidname],
		[overriddencreatedon],
		[SinkCreatedOn],
		[SinkModifiedOn],
		[statecode],
		[statuscode],
		[timezoneruleversionnumber],
		[utcconversiontimezonecode],
		[versionnumber]
	)
	SELECT 
		stg.[apuk_assessmentevent],
		stg.[apuk_assessmentevent_entitytype],
		stg.[apuk_assessmenteventname],
		stg.[apuk_assessor],
		stg.[apuk_assessor_entitytype],
		stg.[apuk_assessorname],
		stg.[apuk_availabilityhours],
		stg.[apuk_availabilityid],
		stg.[apuk_availabilitytype],
		stg.[apuk_availabiltyhours],
		stg.[apuk_contactid],
		stg.[apuk_contactid_entitytype],
		stg.[apuk_contactidname],
		stg.[apuk_contactidyominame],
		stg.[apuk_enddate],
		stg.[apuk_errormessage],
		stg.[apuk_maximumnumberofdays],
		stg.[apuk_name],
		stg.[apuk_startdate],
		stg.[createdby],
		stg.[createdby_entitytype],
		stg.[createdbyname],
		stg.[createdbyyominame],
		stg.[createdon],
		stg.[createdonbehalfby],
		stg.[createdonbehalfby_entitytype],
		stg.[createdonbehalfbyname],
		stg.[createdonbehalfbyyominame],
		stg.[Id],
		stg.[importsequencenumber],
		stg.[modifiedby],
		stg.[modifiedby_entitytype],
		stg.[modifiedbyname],
		stg.[modifiedbyyominame],
		stg.[modifiedon],
		stg.[modifiedonbehalfby],
		stg.[modifiedonbehalfby_entitytype],
		stg.[modifiedonbehalfbyname],
		stg.[modifiedonbehalfbyyominame],
		stg.[organizationid],
		stg.[organizationid_entitytype],
		stg.[organizationidname],
		stg.[overriddencreatedon],
		stg.[SinkCreatedOn],
		stg.[SinkModifiedOn],
		stg.[statecode],
		stg.[statuscode],
		stg.[timezoneruleversionnumber],
		stg.[utcconversiontimezonecode],
		stg.[versionnumber]	
	FROM [staging_ce].[apuk_availability] stg
		LEFT JOIN [synapse_ce].[apuk_availability] tgt
			ON tgt.[id] = stg.[id]
	WHERE tgt.[id] IS NULL
END
